// Oeste Tooltip — Topanga theme (v0.4.8).
// Copy-paste ready. Requires: React 18+, Tailwind with dark: variant, JSX transform.
// Requires Topanga tokens: import src/tokens.css once (or copy src/tokens.json).
// Source: https://github.com/eric2busy/Oeste/blob/main/topanga/src/index.js
// Docs: https://oeste.hiddeninwest.com/topanga/#/components/tooltip
import React from "react";

export function Tooltip({ children, content, side = "top" }) {
  const [open, setOpen] = React.useState(false);
  const [shift, setShift] = React.useState(0);
  const id = React.useId();
  const wrapRef = React.useRef(null);
  const bubbleRef = React.useRef(null);
  React.useLayoutEffect(() => {
    if (!open) return;
    const wrap = wrapRef.current;
    const bubble = bubbleRef.current;
    if (!wrap || !bubble) return;
    const triggerRect = wrap.getBoundingClientRect();
    const bubbleWidth = bubble.getBoundingClientRect().width;
    const margin = 8;
    const center = triggerRect.left + triggerRect.width / 2;
    const half = bubbleWidth / 2;
    let next = 0;
    if (center - half < margin) next = margin - (center - half);
    else if (center + half > window.innerWidth - margin) next = (window.innerWidth - margin) - (center + half);
    setShift(next);
  }, [open, content, side]);
  return (
    <span ref={wrapRef} className="relative inline-block"
      onMouseEnter={() => setOpen(true)} onMouseLeave={() => setOpen(false)}>
      {React.cloneElement(React.Children.only(children), {
        "aria-describedby": id,
        onFocus: () => setOpen(true),
        onBlur: () => setOpen(false),
        onKeyDown: (e) => { if (e.key === "Escape") setOpen(false); },
      })}
      {open && (
        <span ref={bubbleRef} role="tooltip" id={id}
          style={{ transform: `translateX(calc(-50% + ${shift}px))` }}
          className={`absolute left-1/2 z-10 max-w-[calc(100vw-16px)] rounded-md bg-[#1c1917] px-3 py-2 text-xs text-[#f6f4f1] dark:bg-[#f5f3ef] dark:text-[#121110] ${side === "top" ? "bottom-full mb-2" : "top-full mt-2"}`}>
          {content}
        </span>
      )}
    </span>
  );
}
